   if(e.code==='KeyH'&&this.started){this.mode==='helpScreen'?this.resume():this.pause('helpScreen');return;}
   if(e.code==='KeyM'&&this.started){this.mode==='mapScreen'?this.resume():this.pause('mapScreen');return;}
