 look(dx,dy){this.cam.yaw+=dx*.0024*this.sensitivity;this.cam.pitch=V.clamp(this.cam.pitch-dy*.002*this.sensitivity*(this.invert?-1:1),-.95,.65);this.lookAtTime=this.time;}
 reload(){if(this.player.carId||this.player.transition)return;const w=D.weapons[this.player.weapon];if(this.mags[this.player.weapon].startReload(w.reload))this.audio.beep(320,.08);}
