  let prompt='';if(p.transition)prompt='승하차 중…';else if(c)prompt=Math.abs(c.speed)<2?'E  하차 · W  가속':'S  제동 · SPACE  핸드브레이크';else if(Math.hypot(p.pos[0]+126,p.pos[2]-97)<3)prompt='E  체력·탄약 보급';else{const nearby=this.cars.find(c=>c.hp>0&&Math.hypot(c.x-p.pos[0],c.z-p.pos[2])<4.4);if(nearby)prompt='E  '+(nearby.id==='target'?'목표 차량 확보':'차량 탑승');else if(!p.cover&&this.world.findCover(p.pos))prompt='Q  엄폐';}if(c&&c.id==='target'&&Math.hypot(c.x+108,c.z-104)<13)prompt=this.wanted.level?'수배를 먼저 해제하세요.':Math.abs(c.speed)>.5?'차고 구역 안에서 정차하세요.':'차량 인도 확인 중…';$('prompt').style.display=prompt?'block':'none';$('prompt').textContent=prompt;
